  "Open a PDF, Word file, book or web page. Read it here and chat with it — every answer shows the page it came from. Everything stays on your phone.": "একটা PDF, Word ফাইল, বই বা ওয়েব পেজ খুলুন। এখানে পড়ুন আর এর সাথে চ্যাট করুন — প্রতিটি উত্তর কোন পেজ থেকে এসেছে দেখায়। সবকিছু আপনার ফোনেই থাকে।",
