  "A quarter of the window is held back for the answer — a prompt that exactly fills the context leaves no room to reply.": "উইন্ডোর এক-চতুর্থাংশ উত্তরের জন্য রাখা হয় — যে প্রম্পট কনটেক্সট পুরো ভরে ফেলে, তাতে উত্তরের জায়গা থাকে না।",
