  "— it thinks about meaning, not just filler words.": "— এটা শুধু বাড়তি শব্দ না, অর্থ নিয়ে ভাবে।",
  "Text to rewrite": "যে লেখা নতুন করে লিখবেন",
  "Paste AI-generated or stiff text — it comes back sounding like a person wrote it.": "AI-এর লেখা বা কাঠখোট্টা লেখা পেস্ট করুন — মানুষের লেখার মতো হয়ে ফিরে আসবে।",
  "Your writing sample": "আপনার লেখার নমুনা",
  "(this is what makes it sound like you)": "(এটাই লেখাকে আপনার মতো করে তোলে)",
  "Paste a few paragraphs you wrote yourself — an email, a message, anything in your natural voice.": "নিজের লেখা কয়েকটা অনুচ্ছেদ পেস্ট করুন — একটা ইমেইল, মেসেজ, আপনার স্বাভাবিক ভঙ্গিতে যেকোনো কিছু।",
  "Keeps your meaning and facts exactly — changes only how it reads. The writing sample is optional but makes the biggest difference.": "আপনার অর্থ আর তথ্য হুবহু রাখে — শুধু পড়ার ধরন বদলায়। লেখার নমুনা ঐচ্ছিক, কিন্তু সবচেয়ে বড় পার্থক্য এটাই আনে।",
  "Rewritten": "নতুন করে লেখা",
  "Paste stiff or AI-sounding text, add a sample of your own writing, and it comes back in your voice — same meaning, human rhythm.": "কাঠখোট্টা বা AI-এর মতো লেখা পেস্ট করুন, নিজের লেখার একটা নমুনা দিন, আর সেটা আপনার ভঙ্গিতে ফিরে আসবে — একই অর্থ, মানুষের ছন্দ।",
  "Chat through Attune — it reads the whole conversation and sharpens every next prompt.": "Attune-এর মাধ্যমে চ্যাট করুন — এটা পুরো কথোপকথন পড়ে আর পরের প্রতিটি প্রম্পট আরও ধারালো করে।",
  "What do you want out of this whole conversation? (optional, but it makes every prompt better)": "এই পুরো কথোপকথন থেকে কী চান? (ঐচ্ছিক, কিন্তু প্রতিটি প্রম্পট ভালো করে)",
  "Bring the chat from {t} — paste the whole conversation or just its last reply:": "{t} থেকে চ্যাট আনুন — পুরো কথোপকথন বা শুধু শেষ উত্তরটা পেস্ট করুন:",
  "Paste here…": "এখানে পেস্ট করুন…",
  "Read it & suggest my reply": "পড়ে আমার উত্তর সাজেস্ট করো",
  "What do you want to ask? Type it however you like.": "কী জিজ্ঞেস করতে চান? যেভাবে খুশি লিখুন।",
  "Optimize my prompt": "আমার প্রম্পট উন্নত করো",
  "The loop: type intent → get an optimized prompt → send it → bring the reply back → each next prompt is sharper. In the phone app, the share-sheet replaces copy-paste entirely.": "চক্রটা: উদ্দেশ্য লিখুন → উন্নত প্রম্পট পান → পাঠান → উত্তর ফিরিয়ে আনুন → পরের প্রতিটি প্রম্পট আরও ধারালো। ফোন অ্যাপে শেয়ার-শিট কপি-পেস্টের জায়গা পুরোপুরি নিয়ে নেয়।",
  "Ready prompt recipes — pick one, fill the blanks, then": "তৈরি প্রম্পট রেসিপি — একটা বাছুন, খালি জায়গা পূরণ করুন, তারপর",
