  "Say what your shop is — the counter with barcodes, stock, customers who owe, staff and the end-of-day close, ready in a minute. Every sale goes into your books.": "আপনার দোকান কী বলুন — বারকোডসহ কাউন্টার, স্টক, বাকিতে কেনা কাস্টমার, কর্মী আর দিনের শেষের হিসাব, এক মিনিটে তৈরি। প্রতিটি বিক্রি আপনার খাতায় চলে যায়।",
  "Start a new system": "নতুন সিস্টেম শুরু করুন",
  "Shop & trading books": "দোকান ও ব্যবসার খাতা",
  "Invoices with VAT, payments and overdue tracking, stock and purchasing, reports — your own accounting, on your phone, in English and Arabic.": "ভ্যাটসহ ইনভয়েস, পেমেন্ট আর বকেয়ার হিসাব, স্টক আর কেনাকাটা, রিপোর্ট — আপনার নিজের হিসাবরক্ষণ, আপনার ফোনে, ইংরেজি ও আরবিতে।",
