  "The first 20 questions were solved.": "প্রথম 20টি প্রশ্ন সমাধান হয়েছে।",
  "The model gave no answer this time — try again, or ask about one question at a time.": "এবার মডেল কোনো উত্তর দেয়নি — আবার চেষ্টা করুন, বা একবারে একটা প্রশ্ন জিজ্ঞেস করুন।",
