  "The lock keeps others out on a shared phone. It is not encryption, and the notes still show in Mind.": "শেয়ার করা ফোনে লক অন্যদের দূরে রাখে। এটি এনক্রিপশন নয়, আর নোটগুলো মাইন্ডে এখনও দেখা যায়।",
