  "Free: keep and search everything. Pro: it files each item by itself (title, summary, tags), reads your photos and answers questions from your Mind.": "ফ্রি: সব কিছু রাখুন ও খুঁজুন। Pro: প্রতিটি জিনিস নিজেই গুছিয়ে রাখে (শিরোনাম, সারাংশ, ট্যাগ), আপনার ছবি পড়ে আর আপনার মাইন্ড থেকে প্রশ্নের উত্তর দেয়।",
