  "The Yusr document wasn't embedded. On the phone it loads from local assets.": "Yusr ডকুমেন্টটি যুক্ত করা হয়নি। ফোনে এটি অ্যাপের নিজস্ব ফাইল থেকে লোড হয়।",
  "Your ledger and every zakāt ruling live here, unchanged, and free forever. Attune adds memory and plain language on top — it never calculates zakāt and never moves money on its own.": "আপনার খাতা আর জাকাতের প্রতিটি বিধান এখানে আছে, অপরিবর্তিত, আর চিরকাল ফ্রি। Attune এর ওপর স্মৃতি আর সহজ ভাষা যোগ করে — এটি কখনো জাকাত হিসাব করে না, আর নিজে থেকে কখনো টাকা সরায় না।",
  "Share a payment": "একটি পেমেন্ট শেয়ার করুন",
  "An InstaPay confirmation, a bank SMS, a wallet receipt or a photo of one. Attune reads the amount and who it was, then opens your own transaction sheet with it filled in. You pick the account.": "InstaPay কনফার্মেশন, ব্যাংকের SMS, ওয়ালেটের রসিদ বা এগুলোর একটির ছবি। Attune টাকার পরিমাণ আর কাকে দেওয়া হয়েছে তা পড়ে, তারপর আপনার লেনদেনের শিট সেগুলো ভরে খুলে দেয়। অ্যাকাউন্ট আপনি বেছে নেন।",
  "تم تحويل مبلغ 1,500.00 جنيه إلى AHMED MOHAMED. رقم العملية 987654321": "تم تحويل مبلغ 1,500.00 جنيه إلى AHMED MOHAMED. رقم العملية 987654321",
  "Read it": "পড়ুন",
