  "This phone can't write that photo type — try JPG or PNG.": "এই ফোন এই ধরনের ছবি লিখতে পারে না — JPG বা PNG চেষ্টা করুন।",
  "This photo can't be opened here (HEIC photos: convert them to PDF instead).": "এই ছবিটি এখানে খোলা যায় না (HEIC ছবি: বরং PDF-এ কনভার্ট করুন)।",
  "No text was found in that file.": "ওই ফাইলে কোনো টেক্সট পাওয়া যায়নি।",
  "This PDF has no clear table, so each line became a row — check the columns.": "এই PDF-এ স্পষ্ট কোনো টেবিল নেই, তাই প্রতিটি লাইন একটি সারি হয়েছে — কলামগুলো দেখে নিন।",
  "Type the pages to keep, like 1-3, 5": "যে পৃষ্ঠাগুলো রাখবেন লিখুন, যেমন 1-3, 5",
  "The PDFs are joined in the order you picked them.": "আপনি যে ক্রমে বেছে নিয়েছেন, PDF-গুলো সেই ক্রমেই জোড়া হয়।",
  "Pages to keep, e.g. 1-3, 5": "যে পৃষ্ঠা রাখবেন, যেমন 1-3, 5",
  "Pages to turn (empty = all)": "যে পৃষ্ঠা ঘোরাবেন (খালি = সব)",
