  "That file isn't an OpenDocument (LibreOffice) file.": "ওই ফাইলটি OpenDocument (LibreOffice) ফাইল নয়।",
  "That file has no sheet.": "ওই ফাইলে কোনো শিট নেই।",
  "That file isn't an e-book (.epub).": "ওই ফাইলটি ই-বুক (.epub) নয়।",
  "That file isn't a Rich Text (.rtf) file.": "ওই ফাইলটি রিচ টেক্সট (.rtf) ফাইল নয়।",
  "That JSON file has a mistake in it — it can't be read.": "ওই JSON ফাইলে ভুল আছে — এটি পড়া যাচ্ছে না।",
  "No subtitles were found in that file.": "ওই ফাইলে কোনো সাবটাইটেল পাওয়া যায়নি।",
  "None of those page numbers are in this PDF.": "ওই পৃষ্ঠা নম্বরগুলোর কোনোটিই এই PDF-এ নেই।",
