  "The AI reads the text in the photo — Arabic too.": "AI ছবির লেখা পড়ে — আরবিও।",
  "Scanned pages (pictures of paper) are read by the AI.": "স্ক্যান করা পৃষ্ঠা (কাগজের ছবি) AI পড়ে।",
  "Reading the file…": "ফাইল পড়ছে…",
  "The AI is reading scanned page {n} of {t}…": "AI {t}টির মধ্যে {n} নম্বর স্ক্যান করা পৃষ্ঠা পড়ছে…",
  "The AI is reading photo {n} of {t}…": "AI {t}টির মধ্যে {n} নম্বর ছবি পড়ছে…",
  "Making the {t} file…": "{t} ফাইল তৈরি হচ্ছে…",
