  "Documents, fleet records, copilot, every domain pack": "ডকুমেন্ট, ফ্লিট রেকর্ড, কোপাইলট, প্রতিটি ডোমেইন প্যাক",
  "Small enough to download on mobile data if you need to.": "দরকার হলে মোবাইল ডেটায় নামানোর মতো ছোট।",
  "This is a large model for a phone. It will run, and it will slow down noticeably once the phone gets warm — keep answers short, or pick the smaller one.": "ফোনের জন্য এটি বড় মডেল। চলবে, কিন্তু ফোন গরম হলে বেশ ধীর হয়ে যাবে — উত্তর ছোট রাখুন, অথবা ছোটটি নিন।",
  "Every tool, and all 31 country packs": "সব টুল, আর ৩১টি দেশের সব প্যাক",
  "Finds what you promised people, from your own words": "আপনার নিজের কথা থেকে মানুষকে দেওয়া প্রতিশ্রুতি খুঁজে দেয়",
  "Fixed randomness, so a workflow gives identical output every time it runs.": "নির্দিষ্ট র‍্যান্ডমনেস, যাতে একটি ওয়ার্কফ্লো প্রতিবার একই আউটপুট দেয়।",
  "Free web search: DuckDuckGo, Bing and Mojeek at once, then the top pages are read in full, so answers come from real passages.": "ফ্রি ওয়েব সার্চ: DuckDuckGo, Bing ও Mojeek একসঙ্গে, তারপর শীর্ষ পেজগুলো পুরোটা পড়া হয়, তাই উত্তর আসে আসল অনুচ্ছেদ থেকে।",
  "Free · no key": "ফ্রি · কী লাগে না",
  "Installing… {p}%": "ইনস্টল হচ্ছে… {p}%",
  "It remembers everything and can search it": "সবকিছু মনে রাখে আর খুঁজে দিতে পারে",
  "Learns your vocabulary and writes the way you do": "আপনার শব্দভাণ্ডার শেখে আর আপনার মতো করে লেখে",
  "No account, no sign-in, nothing uploaded": "অ্যাকাউন্ট নেই, সাইন-ইন নেই, কিছু আপলোড হয় না",
  "Running": "চলছে",
  "Loading the model…": "মডেল লোড হচ্ছে…",
  "Nothing in the app can reach the internet — no web lookup, no maps, no downloads. The model and everything on the phone keep working.": "অ্যাপের কিছুই ইন্টারনেটে যেতে পারে না — ওয়েবে খোঁজা, ম্যাপ, ডাউনলোড কিছুই নয়। মডেল আর ফোনের সবকিছু চলতে থাকে।",
  "The model reasons first on every question. Clearly better on hard problems, but on a phone the answer starts 30–90 s later. Off: tap “Think” on just the questions that need it.": "প্রতিটি প্রশ্নে মডেল আগে ভাবে। কঠিন সমস্যায় স্পষ্টতই ভালো, কিন্তু ফোনে উত্তর শুরু হতে ৩০–৯০ সেকেন্ড দেরি হয়। বন্ধ থাকলে: যে প্রশ্নে দরকার শুধু সেখানে “ভাবা” ট্যাপ করুন।",
  "The same model as below, given the memory to hold a whole book of context at once. On a 48 GB machine the spare RAM is better spent on context than on precision — you can hand it an entire contract or a year of notes and it keeps all of it in view.": "নিচেরটির মতোই মডেল, কিন্তু একটি পুরো বইয়ের কনটেক্সট ধরার মতো মেমরি দেওয়া। ৪৮ GB মেশিনে বাড়তি RAM নির্ভুলতার চেয়ে কনটেক্সটে কাজে লাগে — একটি পুরো চুক্তি বা এক বছরের নোট দিলেও সব চোখের সামনে থাকে।",
  "The whole assistant, on your device": "পুরো অ্যাসিস্ট্যান্ট, আপনার ডিভাইসে",
