  "When? Pick the date and time.": "কখন? তারিখ ও সময় বেছে নিন।",
  "That time has already passed — pick a later one.": "সেই সময় পেরিয়ে গেছে — পরের একটি সময় বেছে নিন।",
  "That is more than a year away — check the date.": "এটা এক বছরের বেশি দূরে — তারিখ দেখে নিন।",
