  "writes {w}/s · reads {r}/s": "লেখে {w}/সে · পড়ে {r}/সে",
  "Fastest here so far: {m}": "এখানে এ পর্যন্ত সবচেয়ে দ্রুত: {m}",
  "This phone has no GPU the engine can use (no OpenCL driver) — it stays on the CPU.": "এই ফোনে ইঞ্জিনের ব্যবহারযোগ্য GPU নেই (OpenCL ড্রাইভার নেই) — CPU-তেই থাকবে।",
  "Last time, starting on the GPU closed the app. Attune is back on the CPU; you can try the GPU again in Engine → Speed.": "গতবার GPU-তে শুরু করায় অ্যাপ বন্ধ হয়ে গিয়েছিল। Attune আবার CPU-তে আছে; ইঞ্জিন → গতিতে আবার GPU চেষ্টা করতে পারেন।",
  "Chart capacity": "চার্টের ক্ষমতা",
  "{g} t of {c} t = {p}% of the chart": "{c} টনের মধ্যে {g} টন = চার্টের {p}%",
  "Spare: {s} t": "বাকি: {s} টন",
