  "What are the key points?": "মূল পয়েন্টগুলো কী?",
  "Checklist: what every answer must satisfy (one per line, optional)": "চেকলিস্ট: প্রতিটি উত্তরকে যা মানতে হবে (প্রতি লাইনে একটি, ঐচ্ছিক)",
  "Facts the AI should know (prices, rules, terms — optional)": "যা AI-এর জানা উচিত (দাম, নিয়ম, শর্ত — ঐচ্ছিক)",
  "Separate topics with an empty line. Only the paragraphs that fit the question are used, so this can be long.": "বিষয়গুলো একটি ফাঁকা লাইন দিয়ে আলাদা করুন। প্রশ্নের সঙ্গে মেলে এমন অনুচ্ছেদই শুধু ব্যবহার হয়, তাই এটা লম্বা হতে পারে।",
  "Facts": "তথ্য",
  "It also runs this small program on your phone (offline, in a locked box — no internet, no files, no access to the app)": "এটি আপনার ফোনে এই ছোট প্রোগ্রামটিও চালায় (অফলাইনে, তালাবদ্ধ বাক্সে — ইন্টারনেট নেই, ফাইল নেই, অ্যাপে প্রবেশ নেই)",
  "Edit or improve my CV": "আমার সিভি এডিট বা উন্নত করুন",
  "Say what to add or change («add my job at Dar Al Fouad Hospital as a nurse, 2019–2022», «change my phone to …»), or leave it empty and just make it more professional. You see the result before it is kept.": "কী যোগ বা বদল করবেন বলুন («নার্স হিসেবে Dar Al Fouad Hospital-এ আমার চাকরি যোগ করো, ২০১৯–২০২২», «আমার ফোন নম্বর বদলে …»), অথবা খালি রেখে শুধু আরও পেশাদার করতে বলুন। রাখার আগে ফলাফল দেখতে পাবেন।",
  "What should be added or changed? (optional)": "কী যোগ বা বদল করবেন? (ঐচ্ছিক)",
  "Apply my change": "আমার বদল প্রয়োগ করুন",
