  "Could not open that picture": "ছবিটি খোলা যায়নি",
  "Could not save": "সেভ করা যায়নি",
  "Current photo quality in 4 steps: people, places, products and text in pictures. Also edits a photo you give it (“make it night”, “remove the car”).": "৪ ধাপে বর্তমান ছবির মান: মানুষ, জায়গা, পণ্য আর ছবির লেখা। আপনার দেওয়া ছবিও এডিট করে (“রাত করে দাও”, “গাড়িটা সরাও”)।",
  "Describe the picture, in Arabic or English — e.g. “a felucca on the Nile at sunset”": "ছবির বর্ণনা দিন, আরবি বা ইংরেজিতে — যেমন “সূর্যাস্তে নীল নদে একটি ফেলুকা”",
  "Developing the picture…": "ছবি তৈরি হচ্ছে…",
  "Download it on Wi-Fi. After that, pictures are made with no internet at all.": "Wi-Fi-তে ডাউনলোড করুন। এরপর ছবি একেবারে ইন্টারনেট ছাড়াই তৈরি হয়।",
  "Draw it": "আঁকুন",
  "Draw it in Studio": "স্টুডিওতে আঁকুন",
  "A place — Maps finds it": "একটি জায়গা — ম্যাপ খুঁজে দেয়",
  "Show on the map": "ম্যাপে দেখান",
  "Draw on the graphics chip (faster; switches itself off if the driver fails)": "গ্রাফিক্স চিপে আঁকুন (দ্রুত; ড্রাইভার ব্যর্থ হলে নিজেই বন্ধ হয়)",
  "Drawing on the GPU failed, so Attune switched Studio to the CPU. ": "GPU-তে আঁকা ব্যর্থ হয়েছে, তাই Attune স্টুডিও CPU-তে নিয়েছে। ",
  "Drawing — step {n} of {t}": "আঁকা হচ্ছে — {t}-এর {n} ধাপ",
  "Each picture is made by a separate engine process: when it finishes, all its memory goes back to the phone. Nothing is uploaded.": "প্রতিটি ছবি আলাদা ইঞ্জিন প্রক্রিয়ায় তৈরি হয়: শেষ হলে এর সব মেমরি ফোনে ফিরে যায়। কিছুই আপলোড হয় না।",
  "Edit a photo": "ছবি এডিট করুন",
  "Edit it": "এডিট করুন",
  "Edit this": "এটা এডিট করুন",
  "GB, once": "GB, একবার",
