  "Loading the picture model… {p}%": "ছবির মডেল লোড হচ্ছে… {p}%",
  "Makes a finished picture four times bigger and sharper — for printing or zooming in.": "তৈরি ছবিকে চার গুণ বড় ও শার্প করে — প্রিন্ট বা জুম করার জন্য।",
  "Pick a photo": "একটি ছবি বেছে নিন",
  "Pick the photo to edit first.": "আগে এডিট করার ছবি বেছে নিন।",
