  "Searching the web…": "ওয়েবে খোঁজা হচ্ছে…",
  "FLUX.2 klein 4B · high quality": "FLUX.2 klein 4B · উচ্চ মান",
  "The best pictures this phone can make: the 8-bit build of FLUX.2 klein — finer detail, cleaner faces, hands and text. Also edits your photos by instruction.": "এই ফোন যত ভালো ছবি বানাতে পারে: FLUX.2 klein-এর ৮-বিট বিল্ড — সূক্ষ্ম খুঁটিনাটি, পরিষ্কার মুখ, হাত ও লেখা। নির্দেশ দিয়ে আপনার ছবিও এডিট করে।",
  "That file is too large (15 MB at most)": "ফাইলটি খুব বড় (সর্বোচ্চ ১৫ MB)",
  "What's in this file? Summarise what matters.": "এই ফাইলে কী আছে? যা জরুরি তার সারসংক্ষেপ করুন।",
  "Checked — the reviewer fixed a mistake": "যাচাই হয়েছে — রিভিউয়ার একটি ভুল ঠিক করেছে",
  "{n} tries disagreed — weighed and checked": "{n}টি চেষ্টা মেলেনি — ওজন করে যাচাই হয়েছে",
  "{v} of {n} tries agreed · checked": "{n}টির মধ্যে {v}টি চেষ্টা মিলেছে · যাচাই হয়েছে",
