  "Wrong? Teach the right answer": "ভুল? সঠিক উত্তর শিখিয়ে দিন",
  "What should it have said? Chat will answer this way next time you ask something like it.": "কী বলা উচিত ছিল? পরের বার এমন কিছু জিজ্ঞেস করলে চ্যাট এভাবে উত্তর দেবে।",
  "The right answer": "সঠিক উত্তর",
  "Why (optional) — e.g. “the marble falls out when the glass is turned over”": "কেন (ঐচ্ছিক) — যেমন “গ্লাস উল্টালে মার্বেল পড়ে যায়”",
  "Learned — Chat will use this on similar questions": "শেখা হয়েছে — একই ধরনের প্রশ্নে চ্যাট এটা ব্যবহার করবে",
  "That is the same as the answer — nothing to learn": "এটা উত্তরের মতোই — শেখার কিছু নেই",
  "Thinking it through…": "ভালো করে ভাবা হচ্ছে…",
  "Answers agree — a strict check…": "উত্তর মিলেছে — কড়া যাচাই চলছে…",
  "The tries disagree — weighing them…": "চেষ্টাগুলো মেলেনি — ওজন করে দেখা হচ্ছে…",
